fn nanquantile(mut a: Vec<i8>, q: i8) -> i8 {
    assert!(!a.is_empty(), "Array must be non-empty");
    assert!(q >= 0 && q <= 100, "Quantile percentage must be between 0 and 100 inclusive");

    let min_val = get_min_val(&a);
    let max_val = get_max_val(&a);

    if q == 0 {
        return min_val;
    }
    if q == 100 {
        return max_val;
    }

    // Sort the array to find the quantile element
    a.sort_unstable();

    let n = a.len();
    // Compute the fractional index for the quantile q
    // For example, q=50 and n=5 => idx = 50/100 * (5 - 1) = 2.0
    // Use floor of index to pick quantile element (nearest lower index)
    let idx_f = (q as f64 / 100.0) * ((n - 1) as f64);
    let idx = idx_f.floor() as usize;

    a[idx]
}